/// `EOR_asimdsame_only`.
///
/// Split on the word bits `0x40000000`.
///
/// Cut: ENV, V_read, V_set.
pub(super) fn EOR_asimdsame_only(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::EOR_asimdsame_only;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    match word & 0x40000000 {
        0x00000000 => {
            let s1: u128 = (w >> 0) & 0x1f;
            let s2: u128 = (w >> 5) & 0x1f;
            let s3: u128 = (w >> 16) & 0x1f;
            let s4: i128 = s1 as i128;
            let s5: i128 = s2 as i128;
            let s6: i128 = s3 as i128;
            let v7 = st.v_read(b, s5 as u32, 64);
            let v8 = st.v_read(b, s6 as u32, 64);
            let v9 = b.konst(Width::new(64), 0x0);
            let v10 = b.bin(BinOp::Xor, v9, v7);
            let v11 = b.konst(Width::new(64), 0xffffffffffffffff);
            let v12 = b.bin(BinOp::And, v10, v11);
            let v13 = b.bin(BinOp::Xor, v8, v12);
            st.v_set(b, s4 as u32, v13, None);
            Ok(())
        }
        0x40000000 => {
            let s1: u128 = (w >> 0) & 0x1f;
            let s2: u128 = (w >> 5) & 0x1f;
            let s3: u128 = (w >> 16) & 0x1f;
            let s4: i128 = s1 as i128;
            let s5: i128 = s2 as i128;
            let s6: i128 = s3 as i128;
            let v7 = st.v_read(b, s5 as u32, 128);
            let v8 = st.v_read(b, s6 as u32, 128);
            let v9 = b.konst(Width::new(128), 0x0);
            let v10 = b.bin(BinOp::Xor, v9, v7);
            let v11 = b.konst(Width::new(128), 0xffffffffffffffffffffffffffffffff);
            let v12 = b.bin(BinOp::And, v10, v11);
            let v13 = b.bin(BinOp::Xor, v8, v12);
            st.v_set(b, s4 as u32, v13, None);
            Ok(())
        }
        _ => unreachable!(),
    }
}

